def truncate(s, limit):
    b = s.encode("utf-8")
    if len(b) <= limit:
        return s
    cut = limit
    # continuation bytes look like 10xxxxxx; back up until we are not on one
    while cut > 0 and (b[cut] & 0b11000000) == 0b10000000:
        cut -= 1
    return b[:cut].decode("utf-8")

for ch in ["A", "\u00e9", "\u20ac", "\U0001F600"]:
    b = ch.encode("utf-8")
    print(repr(ch), len(b), "bytes", " ".join(format(x, "08b") for x in b))

s = "ab\u20acd"                    # bytes: a b E2 82 AC d  (6 bytes)
print("full:", s, len(s.encode()))
for limit in (3, 4, 5):
    t = truncate(s, limit)
    print("limit", limit, "->", repr(t), len(t.encode()), "bytes")

class Resource:
    def __init__(self, name):
        self.name = name
    def __enter__(self):
        print("enter", self.name)
        return self                # bound to the name after 'as'
    def __exit__(self, exc_type, exc, tb):
        print("exit ", self.name, "exception:", exc_type.__name__ if exc_type else None)
        return False               # falsy: do not swallow the exception

def early():
    with Resource("A"):
        return "returned"          # __exit__ still runs

print(early())

try:
    with Resource("B"):
        raise ValueError("boom")
except ValueError as e:
    print("caught", e)

