import sys, importlib.abc, importlib.util

SOURCES = {"a": "import b\nX = 1\ndef f(): return b.Y + X\n"}
B_VARIANTS = {
    "from-import": "from a import X\nY = X + 1\n",
    "module-import": "import a\nY = 2\n",
}

class Finder(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    def find_spec(self, name, path, target=None):
        if name in SOURCES:
            return importlib.util.spec_from_loader(name, self)
    def create_module(self, spec):
        return None
    def exec_module(self, module):
        exec(SOURCES[module.__name__], module.__dict__)

sys.meta_path.insert(0, Finder())

for variant, src in B_VARIANTS.items():
    SOURCES["b"] = src
    for n in ("a", "b"):
        sys.modules.pop(n, None)       # start fresh each time
    try:
        import a                       # a -> b -> a (a is only half run)
        print(variant, "-> works, f() =", a.f())
    except ImportError as e:
        print(variant, "-> ImportError:", e)

import hashlib

# A lock file records an exact version and the expected hash of each file.
artifact = b"pretend this is the bytes of requests-2.31.0.whl"
LOCK = {
    "requests==2.31.0": hashlib.sha256(artifact).hexdigest(),
}

def install(name, blob):
    digest = hashlib.sha256(blob).hexdigest()
    if digest != LOCK[name]:
        return name + ": REJECTED (hash mismatch)"
    return name + ": ok (" + digest[:12] + "...)"

print("lock:", {k: v[:12] + "..." for k, v in LOCK.items()})
print(install("requests==2.31.0", artifact))
tampered = artifact + b" plus malware"
print(install("requests==2.31.0", tampered))

# a range allows many versions; a lock fixes exactly one
def satisfies(version, low, high):
    to_t = lambda v: tuple(int(x) for x in v.split("."))
    return to_t(low) <= to_t(version) < to_t(high)

for v in ("2.30.0", "2.31.0", "2.32.3", "3.0.0"):
    print("range >=2.31,<3 allows", v, ":", satisfies(v, "2.31", "3"))
